using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BusinessManagement.Infrastructure.Persistence;

public sealed class InitialModelConfiguration : IEntityTypeConfiguration<Business>
{
    public void Configure(EntityTypeBuilder<Business> b)
    {
        b.ToTable("businesses"); b.HasKey(x => x.Id); b.Property(x => x.Name).HasMaxLength(200).IsRequired(); b.Property(x => x.CurrencyCode).HasMaxLength(3).IsRequired(); b.Property(x => x.TimeZone).HasMaxLength(100).IsRequired(); b.Property(x => x.Id).HasColumnType("uuid").ValueGeneratedNever(); b.Property(x => x.CreatedAtUtc).HasColumnType("timestamp with time zone").IsRequired(); b.Property(x => x.UpdatedAtUtc).HasColumnType("timestamp with time zone").IsRequired();
    }
}

public sealed class InitialModelConfigurationSet : IEntityTypeConfiguration<UserAccount>, IEntityTypeConfiguration<BusinessUser>, IEntityTypeConfiguration<Role>, IEntityTypeConfiguration<Permission>, IEntityTypeConfiguration<RolePermission>, IEntityTypeConfiguration<AuditLog>, IEntityTypeConfiguration<Category>, IEntityTypeConfiguration<Product>, IEntityTypeConfiguration<Warehouse>, IEntityTypeConfiguration<StockBalance>, IEntityTypeConfiguration<StockMovement>, IEntityTypeConfiguration<Supplier>, IEntityTypeConfiguration<Purchase>, IEntityTypeConfiguration<PurchaseItem>, IEntityTypeConfiguration<Customer>, IEntityTypeConfiguration<Sale>, IEntityTypeConfiguration<SaleItem>, IEntityTypeConfiguration<Department>, IEntityTypeConfiguration<Employee>, IEntityTypeConfiguration<AttendanceRecord>, IEntityTypeConfiguration<LeaveRequest>, IEntityTypeConfiguration<SalaryStructure>, IEntityTypeConfiguration<PayPeriod>, IEntityTypeConfiguration<SalaryRecord>, IEntityTypeConfiguration<SalaryRecordItem>, IEntityTypeConfiguration<Payment>, IEntityTypeConfiguration<PaymentAllocation>, IEntityTypeConfiguration<Expense>, IEntityTypeConfiguration<ExpenseAttachment>
