    public void Configure(EntityTypeBuilder<UserAccount> b) { b.ToTable("users"); b.HasKey(x => x.Id); b.Property(x => x.Email).HasMaxLength(320).IsRequired(); b.Property(x => x.NormalizedEmail).HasMaxLength(320).IsRequired(); b.Property(x => x.DisplayName).HasMaxLength(200).IsRequired(); b.HasIndex(x => x.NormalizedEmail).IsUnique(); Timestamps(b); }
    public void Configure(EntityTypeBuilder<BusinessUser> b) { b.ToTable("business_users"); b.HasKey(x => x.Id); b.HasIndex(x => new { x.BusinessId, x.UserId }).IsUnique(); b.Property(x => x.Status).HasConversion<string>().HasMaxLength(32); b.HasOne(x => x.Business).WithMany(x => x.Members).HasForeignKey(x => x.BusinessId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.User).WithMany(x => x.Memberships).HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Role).WithMany(x => x.Members).HasForeignKey(x => x.RoleId).OnDelete(DeleteBehavior.Restrict); Timestamps(b); }
    public void Configure(EntityTypeBuilder<Role> b) { b.ToTable("roles"); b.HasKey(x => x.Id); b.Property(x => x.Name).HasConversion<string>().HasMaxLength(32).IsRequired(); b.HasIndex(x => x.Name).IsUnique(); Timestamps(b); }
    public void Configure(EntityTypeBuilder<Permission> b) { b.ToTable("permissions"); b.HasKey(x => x.Id); b.Property(x => x.Name).HasMaxLength(100).IsRequired(); b.HasIndex(x => x.Name).IsUnique(); Timestamps(b); }
    public void Configure(EntityTypeBuilder<RolePermission> b) { b.ToTable("role_permissions"); b.HasKey(x => x.Id); b.HasIndex(x => new { x.RoleId, x.PermissionId }).IsUnique(); b.HasOne(x => x.Role).WithMany(x => x.Permissions).HasForeignKey(x => x.RoleId); b.HasOne(x => x.Permission).WithMany(x => x.Roles).HasForeignKey(x => x.PermissionId); Timestamps(b); }
    public void Configure(EntityTypeBuilder<AuditLog> b) { Simple(b, "audit_logs"); b.HasIndex(x => x.BusinessId); b.HasOne(x => x.Business).WithMany(x => x.AuditLogs).HasForeignKey(x => x.BusinessId).OnDelete(DeleteBehavior.Restrict); b.Property(x => x.Action).HasMaxLength(100).IsRequired(); b.Property(x => x.EntityType).HasMaxLength(100).IsRequired(); b.HasIndex(x => new { x.BusinessId, x.OccurredAtUtc }); }
    public void Configure(EntityTypeBuilder<Category> b) { Business(b, "categories"); b.Property(x => x.Name).HasMaxLength(150).IsRequired(); b.HasIndex(x => new { x.BusinessId, x.Name }).IsUnique(); }
