    public void Configure(EntityTypeBuilder<Warehouse> b) { Business(b, "warehouses"); b.Property(x => x.Name).HasMaxLength(150).IsRequired(); b.HasIndex(x => new { x.BusinessId, x.Name }).IsUnique(); }
    public void Configure(EntityTypeBuilder<StockBalance> b) { Business(b, "stock_balances"); b.Property(x => x.Quantity).HasPrecision(18, 3); b.HasIndex(x => new { x.BusinessId, x.WarehouseId, x.ProductId }).IsUnique(); b.HasOne(x => x.Warehouse).WithMany(x => x.StockBalances).HasForeignKey(x => x.WarehouseId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Product).WithMany(x => x.StockBalances).HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<StockMovement> b) { Business(b, "stock_movements"); b.Property(x => x.MovementType).HasConversion<string>().HasMaxLength(32); b.Property(x => x.QuantityDelta).HasPrecision(18, 3); b.Property(x => x.UnitCost).HasPrecision(18, 2); b.HasIndex(x => new { x.BusinessId, x.ProductId, x.OccurredAtUtc }); b.HasOne(x => x.Warehouse).WithMany(x => x.StockMovements).HasForeignKey(x => x.WarehouseId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Product).WithMany(x => x.StockMovements).HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<Supplier> b) { Business(b, "suppliers"); b.Property(x => x.Name).HasMaxLength(200).IsRequired(); b.HasIndex(x => new { x.BusinessId, x.Name }); }
    public void Configure(EntityTypeBuilder<Purchase> b) { Business(b, "purchases"); b.Property(x => x.PurchaseNumber).HasMaxLength(50).IsRequired(); b.Property(x => x.Status).HasConversion<string>().HasMaxLength(32); b.Property(x => x.TotalAmount).HasPrecision(18, 2); b.HasIndex(x => new { x.BusinessId, x.PurchaseNumber }).IsUnique(); b.HasOne(x => x.Supplier).WithMany(x => x.Purchases).HasForeignKey(x => x.SupplierId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<PurchaseItem> b) { Simple(b, "purchase_items"); b.Property(x => x.Quantity).HasPrecision(18, 3); b.Property(x => x.UnitCost).HasPrecision(18, 2); b.HasOne(x => x.Purchase).WithMany(x => x.Items).HasForeignKey(x => x.PurchaseId); b.HasOne(x => x.Product).WithMany().HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); }
