    public void Configure(EntityTypeBuilder<Sale> b) { Business(b, "sales"); b.Property(x => x.SaleNumber).HasMaxLength(50).IsRequired(); b.Property(x => x.Status).HasConversion<string>().HasMaxLength(32); b.Property(x => x.TotalAmount).HasPrecision(18, 2); b.HasIndex(x => new { x.BusinessId, x.SaleNumber }).IsUnique(); b.HasOne(x => x.Customer).WithMany(x => x.Sales).HasForeignKey(x => x.CustomerId).OnDelete(DeleteBehavior.SetNull); }
    public void Configure(EntityTypeBuilder<SaleItem> b) { Simple(b, "sale_items"); b.Property(x => x.Quantity).HasPrecision(18, 3); b.Property(x => x.UnitPrice).HasPrecision(18, 2); b.HasOne(x => x.Sale).WithMany(x => x.Items).HasForeignKey(x => x.SaleId); b.HasOne(x => x.Product).WithMany().HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<Department> b) { Business(b, "departments"); b.Property(x => x.Name).HasMaxLength(150).IsRequired(); b.HasIndex(x => new { x.BusinessId, x.Name }).IsUnique(); }
    public void Configure(EntityTypeBuilder<Employee> b) { Business(b, "employees"); b.Property(x => x.EmployeeCode).HasMaxLength(50).IsRequired(); b.Property(x => x.FirstName).HasMaxLength(100).IsRequired(); b.Property(x => x.LastName).HasMaxLength(100).IsRequired(); b.Property(x => x.EmploymentStatus).HasConversion<string>().HasMaxLength(32); b.HasIndex(x => new { x.BusinessId, x.EmployeeCode }).IsUnique(); b.HasOne(x => x.Department).WithMany(x => x.Employees).HasForeignKey(x => x.DepartmentId).OnDelete(DeleteBehavior.SetNull); }
    public void Configure(EntityTypeBuilder<AttendanceRecord> b) { Business(b, "attendance_records"); b.Property(x => x.Status).HasConversion<string>().HasMaxLength(32); b.HasIndex(x => new { x.BusinessId, x.EmployeeId, x.WorkDate }).IsUnique(); b.HasOne(x => x.Employee).WithMany(x => x.AttendanceRecords).HasForeignKey(x => x.EmployeeId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<LeaveRequest> b) { Business(b, "leave_requests"); b.Property(x => x.Reason).HasMaxLength(1000).IsRequired(); b.Property(x => x.Status).HasConversion<string>().HasMaxLength(32); b.HasOne(x => x.Employee).WithMany(x => x.LeaveRequests).HasForeignKey(x => x.EmployeeId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<SalaryStructure> b) { Business(b, "salary_structures"); Money(b, x => x.BasicAmount); Money(b, x => x.AllowanceAmount); Money(b, x => x.DeductionAmount); b.HasIndex(x => new { x.BusinessId, x.EmployeeId, x.EffectiveFrom }); b.HasOne(x => x.Employee).WithMany(x => x.SalaryStructures).HasForeignKey(x => x.EmployeeId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<PayPeriod> b) { Business(b, "pay_periods"); b.Property(x => x.Name).HasMaxLength(100).IsRequired(); b.Property(x => x.Status).HasConversion<string>().HasMaxLength(32); b.HasIndex(x => new { x.BusinessId, x.StartDate, x.EndDate }).IsUnique(); }
    public void Configure(EntityTypeBuilder<SalaryRecord> b) { Business(b, "salary_records"); Money(b, x => x.GrossAmount); Money(b, x => x.DeductionAmount); Money(b, x => x.NetAmount); b.Property(x => x.Status).HasConversion<string>().HasMaxLength(32); b.HasIndex(x => new { x.BusinessId, x.EmployeeId, x.PayPeriodId }).IsUnique(); b.HasOne(x => x.Employee).WithMany(x => x.SalaryRecords).HasForeignKey(x => x.EmployeeId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.PayPeriod).WithMany(x => x.SalaryRecords).HasForeignKey(x => x.PayPeriodId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<SalaryRecordItem> b) { Simple(b, "salary_record_items"); b.Property(x => x.Name).HasMaxLength(150).IsRequired(); Money(b, x => x.Amount); b.HasOne(x => x.SalaryRecord).WithMany(x => x.Items).HasForeignKey(x => x.SalaryRecordId); }
    public void Configure(EntityTypeBuilder<Payment> b) { Business(b, "payments"); b.Property(x => x.PayeeType).HasConversion<string>().HasMaxLength(32); Money(b, x => x.Amount); b.Property(x => x.PaymentMethod).HasConversion<string>().HasMaxLength(32); b.Property(x => x.Status).HasConversion<string>().HasMaxLength(32); b.HasIndex(x => new { x.BusinessId, x.PaymentDate }); }
    public void Configure(EntityTypeBuilder<PaymentAllocation> b) { Simple(b, "payment_allocations"); Money(b, x => x.Amount); b.HasOne(x => x.Payment).WithMany(x => x.Allocations).HasForeignKey(x => x.PaymentId); }
    public void Configure(EntityTypeBuilder<Expense> b) { Business(b, "expenses"); b.Property(x => x.Description).HasMaxLength(1000).IsRequired(); Money(b, x => x.Amount); b.Property(x => x.Status).HasConversion<string>().HasMaxLength(32); b.HasIndex(x => new { x.BusinessId, x.ExpenseDate }); }
    public void Configure(EntityTypeBuilder<ExpenseAttachment> b) { Simple(b, "expense_attachments"); b.Property(x => x.FileName).HasMaxLength(255).IsRequired(); b.Property(x => x.StorageKey).HasMaxLength(500).IsRequired(); b.HasOne(x => x.Expense).WithMany(x => x.Attachments).HasForeignKey(x => x.ExpenseId); }

    private static void Simple<TEntity>(EntityTypeBuilder<TEntity> b, string table) where TEntity : EntityBase { b.ToTable(table); b.HasKey(x => x.Id); Timestamps(b); }
    private static void Business<TEntity>(EntityTypeBuilder<TEntity> b, string table) where TEntity : BusinessEntity { Simple(b, table); b.HasIndex(x => x.BusinessId); b.HasOne<Business>(nameof(BusinessEntity.Business)).WithMany().HasForeignKey(nameof(BusinessEntity.BusinessId)).OnDelete(DeleteBehavior.Restrict); }
    private static void Timestamps<TEntity>(EntityTypeBuilder<TEntity> b) where TEntity : EntityBase { b.Property(x => x.Id).HasColumnType("uuid").ValueGeneratedNever(); b.Property(x => x.CreatedAtUtc).HasColumnType("timestamp with time zone").IsRequired(); b.Property(x => x.UpdatedAtUtc).HasColumnType("timestamp with time zone").IsRequired(); }
    private static void Money<TEntity>(EntityTypeBuilder<TEntity> b, System.Linq.Expressions.Expression<Func<TEntity, decimal>> property) where TEntity : class { b.Property(property).HasPrecision(18, 2); }
